def hash_tokens(apps, schema_editor):
    # Invite links made before this stored the secret itself; keep them working, store the hash.
    Invite = apps.get_model("accounts", "Invite")
    for i in Invite.objects.all():
        if len(i.token) != 64 or not all(c in "0123456789abcdef" for c in i.token):
            i.token = hashlib.sha256(("dealflow-invite:" + i.token).encode()).hexdigest()
            i.save(update_fields=["token"])



